(288, 'Sistem Pendukung Keputusan Pemilihan Jurusan Siswa Tingkat SMA Berdasarkan Minat dan Kemampuan Menggunakan Metode MOORA Berbasis Web', '<p data-start=\"138\" data-end=\"413\">https://drive.google.com/drive/folders/1IyxH4Gb0DPGS52JCjzrfV4LKGIkRXD-9?usp=drive_link</p>', 'lampirans/ta/svRu60xheAgVDZlCMaQioqF7Ngh5SPSThXeuoeXW.pdf', '2026-04-06 01:26:13', 'diterima', '2026-04-02 04:16:19', '2026-06-09 07:30:37', 1052, 4),
(289, 'Pengembangan Game Puzzle Petualangan ‘Jejak Gajah Mada’ Berbasis Android Dengan Implementasi AI Navigasi Musuh Menggunakan Algoritma A Star', '<span data-path-to-node=\"2,1\" style=\"color: rgb(0, 0, 0); font-family: &quot;Google Sans Text&quot;, sans-serif !important; line-height: 1.15 !important; margin-top: 0px !important;\"><span class=\"citation-21\" style=\"line-height: 1.15 !important; margin-top: 0px !important;\">Tugas akhir ini menghasilkan produk aplikasi game puzzle petualangan berjudul&nbsp;</span><span data-path-to-node=\"2,1\" data-index-in-node=\"78\" style=\"line-height: 1.15 !important; margin-top: 0px !important;\"><span class=\"citation-21\" style=\"line-height: 1.15 !important; margin-top: 0px !important;\">\"Jejak Gajah Mada\"</span></span><span class=\"citation-21\" style=\"line-height: 1.15 !important; margin-top: 0px !important;\">&nbsp;berbasis&nbsp;</span><span data-path-to-node=\"2,1\" data-index-in-node=\"106\" style=\"line-height: 1.15 !important; margin-top: 0px !important;\"><span class=\"citation-21\" style=\"line-height: 1.15 !important; margin-top: 0px !important;\">Android</span></span></span><span data-path-to-node=\"2,2\" style=\"color: rgb(0, 0, 0); font-family: &quot;Google Sans Text&quot;, sans-serif !important; line-height: 1.15 !important; margin-top: 0px !important;\"><sup _ngcontent-ng-c548562702=\"\" class=\"superscript\" data-turn-source-index=\"1\" style=\"font-size: 16px !important; line-height: 1.15 !important; margin-top: 0px !important;\"></sup></span><span data-path-to-node=\"2,3\" style=\"color: rgb(0, 0, 0); font-family: &quot;Google Sans Text&quot;, sans-serif !important; line-height: 1.15 !important; margin-top: 0px !important;\">.&nbsp;</span><span data-path-to-node=\"2,4\" style=\"color: rgb(0, 0, 0); font-family: &quot;Google Sans Text&quot;, sans-serif !important; line-height: 1.15 !important; margin-top: 0px !important;\"><span class=\"citation-20\" style=\"line-height: 1.15 !important; margin-top: 0px !important;\"></span></span><span data-path-to-node=\"2,5\" style=\"color: rgb(0, 0, 0); font-family: &quot;Google Sans Text&quot;, sans-serif !important; line-height: 1.15 !important; margin-top: 0px !important;\">Tujuan dibuatnya aplikasi ini adalah sebagai media pembelajaran sejarah Kerajaan Majapahit yang interaktif dan menarik bagi generasi muda guna meningkatkan kesadaran sejarah dan identitas budaya</span><span data-path-to-node=\"2,6\" style=\"color: rgb(0, 0, 0); font-family: &quot;Google Sans Text&quot;, sans-serif !important; line-height: 1.15 !important; margin-top: 0px !important;\"><span class=\"citation-20 citation-end-20\" style=\"line-height: 1.15 !important; margin-top: 0px !important;\"><source-footnote ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c548562702=\"\" style=\"line-height: 1.15 !important; margin-top: 0px !important;\"><sup _ngcontent-ng-c548562702=\"\" class=\"superscript\" data-turn-source-index=\"2\" style=\"font-size: 16px !important; line-height: 1.15 !important; margin-top: 0px !important;\"></sup></source-footnote><source-footnote ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c548562702=\"\" style=\"line-height: 1.15 !important; margin-top: 0px !important;\"><sup _ngcontent-ng-c548562702=\"\" class=\"superscript\" data-turn-source-index=\"2\" style=\"font-size: 16px !important; line-height: 1.15 !important; margin-top: 0px !important;\"></sup></source-footnote><source-footnote ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c548562702=\"\" style=\"line-height: 1.15 !important; margin-top: 0px !important;\"><sup _ngcontent-ng-c548562702=\"\" class=\"superscript\" data-turn-source-index=\"2\" style=\"font-size: 16px !important; line-height: 1.15 !important; margin-top: 0px !important;\"></sup></source-footnote><source-footnote ng-version=\"0.0.0-PLACEHOLDER\" _nghost-ng-c548562702=\"\" style=\"line-height: 1.15 !important; margin-top: 0px !important;\"><sup _ngcontent-ng-c548562702=\"\" class=\"superscript\" data-turn-source-index=\"