(219, 1958, 2, 'PROYEK PEMBANGUNAN GEDUNG LABORATORIUM TEKNIK UMY', 'pembangunan gedung laboratorium teknik UMY, luasan total 5000 m2 dengan jumlah 4 lantai', 'UMY, YOGYAKARTA', 'MANTRIREJON, YOGYAKARTA DIY', 'lampirans/kp/8jx1LAMghvIN8YhSF5KpR3luRWzEUzjopBxlNUlW.pdf', 'lampirans/kp/7Ag6CGkXyunsTXUJmkUsXxE1ITOJr6HBdUUOwsQ1.pdf', 'diterima', '2026-09-16 06:20:51', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-16 06:17:56', '2026-09-16 06:20:51'),
(220, 1450, 4, 'Presensi Siswa Berbasis QR Code', 'Presensi manual lebih sulit dalam membuat rekap data, tidak efisien. Solusi yang ditawarkan adalah dengan beralih ke model Digital, sehingga bisa memudahkan dalam hal rekap data ataupun mendeteksi ketidak hadiran siswa secara cepat dan efisien.', 'SMA Negeri 1 Kertek', 'Jalan Gatot Subroto Km. 6  Wonosobo', 'lampirans/kp/V3bV6OC2QaA2u5lOJtxtFcBibNdizE7hNVIEbPeA.pdf', 'lampirans/kp/7HdxVjclREMzky0AffjHXqAk4c0PfnBbDNwyljgI.pdf', 'diterima', '2026-10-02 06:33:11', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-18 14:24:10', '2026-10-02 06:33:11'),
