INSERT INTO `revisi_bimbingans` (`id`, `catatan`, `lampiran`, `lampiran_revisi`, `tanggal_bimbingan`, `created_at`, `updated_at`, `bimbingan_id`, `dosen_id`) VALUES
(1405, '<p class=\"MsoListParagraphCxSpFirst\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 14pt;\">1.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size: 14pt;\">Diagram UML Belum Tersedia dalam Bentuk Visual<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Problem: Use Case dan Activity Diagram hanya ditampilkan sebagai tabel simbol + narasi.<o:p></o:p></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Saran: Tambahkan:<o:p></o:p></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 72pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: &quot;Courier New&quot;;\">o<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp; </span></span>Gambar asli Use Case Diagram<o:p></o:p></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 72pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: &quot;Courier New&quot;;\">o<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp; </span></span>Gambar asli Activity Diagram<o:p></o:p></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin: 0cm 0cm 0cm 72pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: &quot;Courier New&quot;;\">o<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp; </span></span>Gambar bisa dibuat dengan draw.io, Lucidchart, atau StarUML.<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><span style=\"font-family: &quot;Times New Roman&quot;, serif;\">&nbsp;</span></p><p class=\"MsoListParagraphCxSpFirst\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\">2.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp; </span><span style=\"font-size: 14pt;\">Subbab Tools (Python, Google Colab) Terlalu Panjang</span><o:p></o:p></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Penjelasan terlalu umum dan tidak langsung relevan dengan konteks penelitian.<o:p></o:p></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Saran:<o:p></o:p></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 72pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: &quot;Courier New&quot;;\">o<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp; </span></span>Gabungkan jadi 1 subbab: \"Perangkat Pendukung\" atau singkat saja pada Bab III nanti.<o:p></o:p></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin: 0cm 0cm 0cm 72pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: &quot;Courier New&quot;;\">o<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp; </span></span>Contoh kalimat:<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0cm 108pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\">Python digunakan untuk implementasi CNN dengan pustaka TensorFlow dan Keras. Google Colab dimanfaatkan sebagai lingkungan cloud-based training.<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><span style=\"font-family: &quot;Times New Roman&quot;, serif;\">&nbsp;</span></p><p class=\"MsoListParagraphCxSpFirst\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 14pt;\">3.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size: 14pt;\">Penjelasan CNN dan Deep Learning Terpisah<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Ada pengulangan fungsi layer CNN di dua tempat (subbab CNN &amp; MobileNet).<o:p></o:p></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Saran: Gabungkan atau rujuk satu subbab agar tidak redundan.<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><span style=\"font-family: &quot;Times New Roman&quot;, serif;\">&nbsp;</span></p><p class=\"MsoListParagraphCxSpFirst\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 14pt;\">4.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size: 14pt;\">Tidak Ada Penjelasan Data Augmentation<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Padahal MobileNet biasa dipasangkan dengan teknik ini untuk memperkaya data training.<o:p></o:p></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Saran: Tambahkan paragraf:<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0cm 72pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\">Dalam penelitian ini, teknik data augmentation seperti flipping, rotation, dan zoom digunakan untuk meningkatkan generalisasi model pada kondisi pencahayaan dan sudut gambar yang bervariasi.<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><span style=\"font-family: &quot;Times New Roman&quot;, serif;\">&nbsp;</span></p><p class=\"MsoListParagraphCxSpFirst\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 14pt;\">5.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size: 14pt;\">Kutipan Elektronik (Blog, Kumparan, Dicoding) Harus Dibatasi<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Penggunaan sumber non-jurnal terlalu banyak (Dicoding, Kumparan).<o:p></o:p></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Saran: Ganti dengan sumber dari jurnal atau buku ilmiah. Misalnya:<o:p></o:p></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 72pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: &quot;Courier New&quot;;\">o<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp; </span></span>Untuk deep learning → gunakan referensi dari Goodfellow et al., 2016<o:p></o:p></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin: 0cm 0cm 0cm 72pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: &quot;Courier New&quot;;\">o<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp; </span></span>Untuk MobileNet → referensi asli dari Howard et al., 2017<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><span style=\"font-family: &quot;Times New Roman&quot;, serif;\">&nbsp;</span></p><p class=\"MsoListParagraphCxSpFirst\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 14pt;\">6.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size: 14pt;\">Klasifikasi Tidak Menyebutkan Dataset Secara Ringkas<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Dataset disebutkan di kajian pustaka, tapi belum dijelaskan umum seperti ukuran dataset, jumlah kelas, dan kondisi pencahayaan.<o:p></o:p></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Saran: Tambahkan sedikit penjelasan awal:<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0cm 108pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\">Klasifikasi dilakukan terhadap dataset berisi gambar stroberi dalam 3 kelas kematangan: mentah, setengah matang, dan matang.<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><span style=\"font-family: &quot;Times New Roman&quot;, serif;\">&nbsp;</span></p><p class=\"MsoListParagraphCxSpFirst\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 14pt;\">7.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size: 14pt;\">Tidak Ada Penutup Ringkasan Bab II<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Bab II langsung ditutup tanpa paragraf kesimpulan.<o:p></o:p></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Saran: Tambahkan kalimat penutup, contoh:<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0cm 72pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\">Bab ini telah membahas teori-teori dasar yang menjadi fondasi dalam pengembangan sistem klasifikasi kematangan stroberi. Pemahaman atas CNN, arsitektur MobileNet, serta studi pustaka terkait menjadi dasar metodologi pengembangan sistem pada Bab III.<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><o:p>&nbsp;</o:p></p>', '/ekapta-app-new/storage/app/public/lampirans/JPagLZcZ9HyqtilEWKoAFkTook1w4rGUyTY75Lil.pdf', NULL, '2025-06-22 14:23:02', '2025-06-22 15:23:02', '2025-06-22 15:23:02', 1894, 19),
(1406, '<p class=\"MsoListParagraphCxSpFirst\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 14pt;\">1.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size: 14pt;\">Judul Tidak Konsisten dengan Isi<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Masalah: Di dokumen tertulis “Menu Siap Jual”, sementara di sampul dan sebagian besar isi menggunakan “Menu Siap Saji”.<o:p></o:p></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Saran: Seragamkan seluruh bagian dokumen, pilih salah satu:<o:p></o:p></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 72pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: &quot;Courier New&quot;;\">o<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp; </span></span>Jika maksudnya makanan siap disajikan = \"Menu Siap Saji\"<o:p></o:p></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin: 0cm 0cm 0cm 72pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: &quot;Courier New&quot;;\">o<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp; </span></span>Jika maksudnya menu sudah jadi dan tinggal dijual = \"Menu Siap Jual\"<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><span style=\"font-family: &quot;Times New Roman&quot;, serif;\">&nbsp;</span></p><p class=\"MsoListParagraphCxSpFirst\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 14pt;\">2.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size: 14pt;\">Latar Belakang Terlalu Panjang dan Teoretis di Awal<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Masalah: Pembahasan tentang definisi sistem informasi dan teknologi informasi terlalu panjang dan tidak langsung ke masalah utama.<o:p></o:p></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Saran:<o:p></o:p></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 72pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: &quot;Courier New&quot;;\">o<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp; </span></span>Ringkas bagian pengantar teori (cukup 2-3 kalimat).<o:p></o:p></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin: 0cm 0cm 0cm 72pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: &quot;Courier New&quot;;\">o<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp; </span></span>Fokus lebih awal pada konteks RM Gendu Roso dan masalah yang dihadapi dalam pengelolaan stok.<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><span style=\"font-family: &quot;Times New Roman&quot;, serif;\">&nbsp;</span></p><p class=\"MsoListParagraphCxSpFirst\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 14pt;\">3.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size: 14pt;\">Batasan Masalah Kurang Rapi dan Konsisten<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Masalah:<o:p></o:p></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 72pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: &quot;Courier New&quot;;\">o<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp; </span></span>Sub poin “b” hanya berisi “Menu Siap Saji yang diprediksi…” tapi tidak lengkap.<o:p></o:p></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 72pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: &quot;Courier New&quot;;\">o<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp; </span></span>Ada pengulangan kata (“menu menu”).<o:p></o:p></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Saran: Tulis ulang batasan masalah menjadi:<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><span style=\"font-size: 10pt; font-family: &quot;Courier New&quot;;\">&nbsp;</span></p><p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0cm 2cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\">a. Sistem ini dirancang khusus untuk RM Gendu Roso, Wonosobo.&nbsp;<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0cm 2cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\">b. Menu yang diprediksi meliputi: [sebutkan nama-nama menu jika ada].&nbsp;<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0cm 2cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\">c. Kriteria input meliputi penjualan dan stok 11 bulan terakhir.&nbsp;<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0cm 2cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\">d. Prediksi dilakukan untuk periode 1 bulan ke depan.&nbsp;<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0cm 2cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\">e. Hanya admin gudang yang dapat mengakses fitur prediksi.&nbsp;<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0cm 2cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\">f. Sistem tidak mempertimbangkan musim, promosi, atau tren khusus.<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><span style=\"font-family: &quot;Times New Roman&quot;, serif;\">&nbsp;</span></p><p class=\"MsoListParagraphCxSpFirst\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 14pt;\">4.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size: 14pt;\">Rumusan Masalah Belum Akademik<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Kalimatnya masih terlalu operasional dan langsung pada sistem.<o:p></o:p></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Saran:<o:p></o:p></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 72pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: &quot;Courier New&quot;;\">o<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp; </span></span>Tambahkan pertanyaan tentang bagaimana mengembangkan sistem dan pendekatan prediktif.<o:p></o:p></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 108pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\">a.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp; </span>Bagaimana merancang sistem prediksi persediaan menu siap saji berbasis Fuzzy Mamdani?<o:p></o:p></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin: 0cm 0cm 0cm 108pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\">b.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp; </span>Bagaimana mengukur akurasi sistem prediksi menggunakan metode evaluasi MAE, RMSE, dan MAPE?<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><span style=\"font-family: &quot;Times New Roman&quot;, serif;\">&nbsp;</span></p><p class=\"MsoListParagraphCxSpFirst\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 14pt;\">5.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size: 14pt;\">Penulisan Sistematika &nbsp;Penulisan Terlalu Naratif<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Menggunakan kalimat “pada bab ini akan membahas…”.<o:p></o:p></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Saran: Ringkas menjadi bentuk struktural dan formal:<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0cm 72pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\">Bab I berisi pendahuluan. Bab II memaparkan landasan teori terkait sistem prediksi dan metode Fuzzy Mamdani. Bab III menjelaskan metodologi penelitian. Bab IV menyajikan hasil dan pembahasan. Bab V memuat kesimpulan dan saran.<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><span style=\"font-family: &quot;Times New Roman&quot;, serif;\">&nbsp;</span></p><p class=\"MsoListParagraphCxSpFirst\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 14pt;\">6.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size: 14pt;\">Kutipan Masih Sedikit dan Terbatas<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Hanya mengutip Romney &amp; Steinbart (2015) dan Islamy et al. (2024).<o:p></o:p></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Saran: Tambahkan referensi pendukung untuk teori fuzzy logic, prediksi stok, dan manajemen persediaan dari jurnal atau buku ilmiah.<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><o:p>&nbsp;</o:p></p>', '/ekapta-app-new/storage/app/public/lampirans/oqhtvTXg2zJmmosHvrz9X6C31KKxyei430E7VPnL.pdf', NULL, '2025-06-19 08:35:49', '2025-06-22 17:04:25', '2025-06-22 17:04:25', 1807, 19);
INSERT INTO `revisi_bimbingans` (`id`, `catatan`, `lampiran`, `lampiran_revisi`, `tanggal_bimbingan`, `created_at`, `updated_at`, `bimbingan_id`, `dosen_id`) VALUES
(1407, '<p class=\"MsoListParagraphCxSpFirst\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 14pt;\">1.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size: 14pt;\">Nomor Subbab dan Penomoran Tabel/Gambar Tidak Konsisten<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Masalah: Ada ketidaksesuaian antara urutan subbab (misal 4.4 muncul berulang kali), dan beberapa gambar tidak memiliki nomor unik yang urut (contoh: Gambar 4.17 muncul dua kali).<o:p></o:p></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Saran:<o:p></o:p></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 72pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: &quot;Courier New&quot;;\">o<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp; </span></span>Koreksi dan konsistenkan penomoran subbab: 4.4.1, 4.4.2, dst.<o:p></o:p></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin: 0cm 0cm 0cm 72pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: &quot;Courier New&quot;;\">o<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp; </span></span>Pastikan seluruh gambar dan tabel diberi nomor unik dan urut.<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><span style=\"font-family: &quot;Times New Roman&quot;, serif;\">&nbsp;</span></p><p class=\"MsoListParagraphCxSpFirst\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 14pt;\">2.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size: 14pt;\">Perlu Menambahkan Visualisasi Fuzzy Secara Grafis<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Fungsi keanggotaan fuzzy dijelaskan hanya dalam bentuk tabel dan teks.<o:p></o:p></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Saran: Tambahkan grafik fungsi keanggotaan segitiga (μ(x)) untuk tiap kategori risiko (rendah, sedang, tinggi, dst).<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><span style=\"font-family: &quot;Times New Roman&quot;, serif;\">&nbsp;</span></p><p class=\"MsoListParagraphCxSpFirst\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 14pt;\">3.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size: 14pt;\">Tabel Input dan Output Hasil Fuzzy Kurang Ilustratif<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Tidak ada contoh konkret input dan hasil fuzzy sebelum dan sesudah inferensi &amp; defuzzifikasi.<o:p></o:p></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Saran: Tambahkan contoh satu kasus lengkap:<o:p></o:p></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 72pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: &quot;Courier New&quot;;\">o<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp; </span></span>Input skala<o:p></o:p></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 72pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: &quot;Courier New&quot;;\">o<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp; </span></span>Derajat keanggotaan (μ)<o:p></o:p></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 72pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: &quot;Courier New&quot;;\">o<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp; </span></span>Aturan yang digunakan<o:p></o:p></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 72pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: &quot;Courier New&quot;;\">o<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp; </span></span>Hasil inferensi<o:p></o:p></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin: 0cm 0cm 0cm 72pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: &quot;Courier New&quot;;\">o<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp; </span></span>Nilai crisp hasil defuzzifikasi<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><span style=\"font-family: &quot;Times New Roman&quot;, serif;\">&nbsp;</span></p><p class=\"MsoListParagraphCxSpFirst\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 14pt;\">4.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size: 14pt;\">Analisis Hasil Evaluasi Kurang Mendalam<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Confusion Matrix dan classification report disebutkan, tapi belum diinterpretasikan secara komparatif terhadap metrik lain (misal overfitting, class imbalance).<o:p></o:p></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Saran: Tambahkan sedikit analisis:<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0cm 72pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\">\"Model memiliki kesulitan membedakan kelas Sedang dan Tinggi, kemungkinan disebabkan distribusi data tidak seimbang atau fitur yang kurang informatif.\"<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><span style=\"font-family: &quot;Times New Roman&quot;, serif;\">&nbsp;</span></p><p class=\"MsoListParagraphCxSpFirst\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 14pt;\">5.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size: 14pt;\">Kekurangan Visualisasi Interaktif Sistem<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Banyak gambar tampilan sistem (dashboard, popup, form) tetapi tidak disebutkan alur interaksi pengguna secara deskriptif.<o:p></o:p></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Saran: Tambahkan skenario:<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0cm 3cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\">\"User login → input data risiko → klik \'Hitung Risiko\' → sistem menghitung dan menampilkan popup hasil → user simpan hasil → bisa melihat riwayat.\"<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><o:p>&nbsp;</o:p></p>', '/ekapta-app-new/storage/app/public/lampirans/tJMxo72kcz9HI4BEU6p2P2Z34AOU4aq5sq0iWS34.pdf', NULL, '2025-06-18 22:52:25', '2025-06-22 17:30:15', '2025-06-22 17:30:15', 1466, 19),
(1408, '<p class=\"MsoListParagraphCxSpFirst\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 14pt;\">1.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size: 14pt;\">Diagram Tidak Diperlihatkan<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Meskipun disebutkan ada gambar (Use Case, Activity, Class, Sequence), tidak ada visual diagram yang tampil di dalam file PDF.<o:p></o:p></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Saran: Lampirkan semua diagram dalam bentuk gambar asli, bukan hanya penjelasan simbol. Gunakan tools seperti:<o:p></o:p></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 72pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: &quot;Courier New&quot;;\">o<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp; </span></span>draw.io<o:p></o:p></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 72pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: &quot;Courier New&quot;;\">o<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp; </span></span>Lucidchart<o:p></o:p></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin: 0cm 0cm 0cm 72pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: &quot;Courier New&quot;;\">o<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp; </span></span>StarUML<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><o:p>&nbsp;</o:p></p><p class=\"MsoListParagraphCxSpFirst\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 14pt;\">2.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size: 14pt;\">Tabel Simbol UML Dapat Diringkas<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Penjabaran simbol UML (tabel Use Case, Activity, Class, Sequence) terlalu panjang dan terkesan berulang.<o:p></o:p></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Saran: Ringkas menjadi satu halaman atau pindahkan ke lampiran, karena ini lebih cocok untuk referensi teknis daripada isi utama bab teori.<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><o:p>&nbsp;</o:p></p><p class=\"MsoListParagraphCxSpFirst\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 14pt;\">3.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size: 14pt;\">Subbab Tools Masih Bisa Dipadatkan<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Laravel, PHP, MySQL, dan Chart.js dijelaskan dalam subbab tersendiri.<o:p></o:p></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Saran: Jadikan satu subbab bernama \"2.1.9 Tools dan Teknologi yang Digunakan\", seperti yang sudah dilakukan, tetapi bisa lebih ringkas tanpa mengulang informasi yang umum diketahui.<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><o:p>&nbsp;</o:p></p><p class=\"MsoListParagraphCxSpFirst\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\">4.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp; </span>&nbsp;<span style=\"font-size: 14pt;\">Kutipan Belum Konsisten Formatnya</span><o:p></o:p></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Sebagian kutipan menggunakan (Nama, Tahun), tapi tanpa daftar pustaka di dokumen ini.<o:p></o:p></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Saran: Gunakan gaya kutipan APA Style atau IEEE, dan pastikan setiap kutipan ada dalam daftar pustaka di akhir laporan.<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><o:p>&nbsp;</o:p></p><p class=\"MsoListParagraphCxSpFirst\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 14pt;\">5.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size: 14pt;\">Tabel di Kajian Pustaka Belum Tersusun Rapi (Format PDF acak)<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Tabel matriks penelitian terlihat tidak sejajar dan sulit dibaca.<o:p></o:p></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Saran: Format ulang tabel agar simetris dan bisa dibaca dengan nyaman (misalnya menggunakan tabel HTML atau format tabel Word sebelum diubah ke PDF).<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><o:p>&nbsp;</o:p></p>', '/ekapta-app-new/storage/app/public/lampirans/jyLXuPCmlyVSoZCpYH8cGaKobPlVSDAcMy3qekTA.pdf', NULL, '2025-06-19 06:02:26', '2025-06-22 17:38:47', '2025-06-22 17:38:47', 1882, 19);
INSERT INTO `revisi_bimbingans` (`id`, `catatan`, `lampiran`, `lampiran_revisi`, `tanggal_bimbingan`, `created_at`, `updated_at`, `bimbingan_id`, `dosen_id`) VALUES
(1409, '<p class=\"MsoListParagraphCxSpFirst\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 14pt;\">1.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size: 14pt;\">Kerangka Pikir Tidak Tertulis atau Ditampilkan<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Masalah: Subbab 3.1 “Kerangka Pikir” kosong/tidak ditampilkan diagramnya.<o:p></o:p></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Saran: Tambahkan:<o:p></o:p></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 72pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: &quot;Courier New&quot;;\">o<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp; </span></span>Diagram kerangka pikir (alur logis pemecahan masalah) misalnya dalam bentuk bagan blok (dari masalah → solusi → metode → hasil).<o:p></o:p></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin: 0cm 0cm 0cm 72pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: &quot;Courier New&quot;;\">o<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp; </span></span>Gunakan tools seperti Canva, PowerPoint, atau draw.io.<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><o:p>&nbsp;</o:p></p><p class=\"MsoListParagraphCxSpFirst\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 14pt;\">2.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size: 14pt;\">Alur Penelitian Hanya Tabel Tanpa Diagram Alir<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Masalah: Disebutkan “gambar alur” tapi hanya ada tabel deskriptif.<o:p></o:p></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Saran: Tambahkan flowchart atau diagram alur penelitian, misalnya:<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0cm 72pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\">Scraping → Cleaning → Preprocessing → Labeling → TF-IDF → SMOTE → SVM → Evaluation → Deployment → Web Evaluation<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><o:p>&nbsp;</o:p></p><p class=\"MsoListParagraphCxSpFirst\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 14pt;\">3.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size: 14pt;\">Gambaran Sistem Tidak Disertai Ilustrasi Visual<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Meskipun dijelaskan secara rinci, tidak ada diagram arsitektur sistem atau skema pipeline.<o:p></o:p></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Saran: Tambahkan skema sistem yang menggambarkan hubungan antara:<o:p></o:p></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 72pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: &quot;Courier New&quot;;\">o<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp; </span></span>Proses pengambilan data<o:p></o:p></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 72pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: &quot;Courier New&quot;;\">o<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp; </span></span>Pelabelan dan training<o:p></o:p></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 72pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: &quot;Courier New&quot;;\">o<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp; </span></span>API Flask<o:p></o:p></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin: 0cm 0cm 0cm 72pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: &quot;Courier New&quot;;\">o<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp; </span></span>Frontend aplikasi web<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><o:p>&nbsp;</o:p></p><p class=\"MsoListParagraphCxSpFirst\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 14pt;\">4.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size: 14pt;\">Tidak Ada Penjelasan Detail Dataset<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Jumlah data, proporsi label positif/negatif/netral, belum disebutkan.<o:p></o:p></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Saran: Tambahkan penjelasan seperti:<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0cm 92.15pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -2.15pt;\">“Dataset terdiri dari 1.200 ulasan yang dipilah menjadi 600 positif, 400 netral, dan 200 negatif.”<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><o:p>&nbsp;</o:p></p><p class=\"MsoListParagraphCxSpFirst\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 14pt;\">5.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size: 14pt;\">Jadwal Penelitian Tidak Diberi Format Gantt Chart<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Formatnya tabel bulanan biasa. Akan lebih menarik secara visual jika ditampilkan sebagai Gantt chart.<o:p></o:p></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Saran: Buat visual timeline menggunakan Excel, Google Sheet, atau GanttProject.<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><o:p>&nbsp;</o:p></p><p class=\"MsoListParagraphCxSpFirst\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 14pt;\">6.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size: 14pt;\">Kutipan dan Referensi Tidak Ditampilkan<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Bab ini mengutip metode dan alat, namun tidak menyertakan referensi jurnal, buku, atau dokumentasi resmi.<o:p></o:p></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Saran: Tambahkan kutipan untuk:<o:p></o:p></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 72pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: &quot;Courier New&quot;;\">o<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp; </span></span>Definisi SVM (mis. Cortes &amp; Vapnik, 1995)<o:p></o:p></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 72pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: &quot;Courier New&quot;;\">o<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp; </span></span>SMOTE (Chawla et al., 2002)<o:p></o:p></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin: 0cm 0cm 0cm 72pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: &quot;Courier New&quot;;\">o<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp; </span></span>TF-IDF (Salton, 1988)<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><o:p>&nbsp;</o:p></p>', '/ekapta-app-new/storage/app/public/lampirans/e7pT0g2ChSkzGr8PaEm4I7RbTDRyiOefocjLgalp.pdf', NULL, '2025-06-17 05:23:30', '2025-06-22 17:48:12', '2025-06-22 17:48:12', 1709, 19),
(1410, '<p class=\"MsoListParagraphCxSpFirst\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 14pt;\">1.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size: 14pt;\">Diagram UML Hanya Tabel Simbol, Belum Disertai Gambar Diagram<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Masalah: Bab II menjelaskan diagram UML (Use Case, Activity, Class, Sequence) hanya dalam bentuk simbol tabel dan deskripsi, tanpa visualisasi diagram yang sesungguhnya.<o:p></o:p></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Saran: Tambahkan:<o:p></o:p></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 72pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: &quot;Courier New&quot;;\">o<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp; </span></span>Gambar Use Case Diagram lengkap (aktor: admin, panitia, siswa)<o:p></o:p></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 72pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: &quot;Courier New&quot;;\">o<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp; </span></span>Activity Diagram alur seleksi dan pengambilan keputusan<o:p></o:p></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 72pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: &quot;Courier New&quot;;\">o<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp; </span></span>Class Diagram sistem SPK<o:p></o:p></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin: 0cm 0cm 0cm 72pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: &quot;Courier New&quot;;\">o<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp; </span></span>Sequence Diagram proses perhitungan Fuzzy SAW<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><o:p>&nbsp;</o:p></p><p class=\"MsoListParagraphCxSpFirst\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 14pt;\">2.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size: 14pt;\">Subbab Tools (PHP, MySQL, VSCode) Terlalu Umum<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Penjelasan cenderung bersifat tutorial atau pengantar umum.<o:p></o:p></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Saran: Ringkas dan fokuskan pada fungsi alat tersebut dalam konteks sistem yang dibangun, misalnya:<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0cm 72pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\">“PHP digunakan sebagai backend untuk mengelola logika fuzzy dan proses seleksi peserta, sedangkan MySQL menyimpan data peserta dan nilai preferensi.”<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><o:p>&nbsp;</o:p></p><p class=\"MsoListParagraphCxSpFirst\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 14pt;\">3.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size: 14pt;\">Penjelasan Fuzzy dan SAW Terpisah, Kurang Sinergi<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Ada dua subbab besar: metode Fuzzy dan metode SAW, tapi tidak dijelaskan bagaimana kedua metode ini digabungkan.<o:p></o:p></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Saran: Tambahkan penjelasan:<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0cm 108pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\">\"Metode Fuzzy digunakan untuk mengubah nilai input menjadi bobot linguistik, sedangkan metode SAW digunakan untuk menghitung nilai akhir dengan menjumlahkan hasil perkalian antara bobot dan nilai preferensi.\"<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><o:p>&nbsp;</o:p></p><p class=\"MsoListParagraphCxSpFirst\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\">4.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp; </span>Penjelasan Perhitungan SAW Belum Dilengkapi Contoh<o:p></o:p></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Dijelaskan rumus dan alur, namun tanpa ilustrasi angka (kasus contoh).<o:p></o:p></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Saran: Tambahkan 1 studi kasus:<o:p></o:p></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin: 0cm 0cm 0cm 72pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: &quot;Courier New&quot;;\">o<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp; </span></span>Misal: 3 siswa, 3 kriteria, tabel nilai, normalisasi, bobot, skor akhir.<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><o:p>&nbsp;</o:p></p><p class=\"MsoListParagraphCxSpFirst\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 14pt;\">5.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size: 14pt;\">Tidak Ada Visualisasi Fungsi Keanggotaan Fuzzy<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Masalah: Fungsi linguistik seperti “rendah”, “sedang”, “tinggi” dijelaskan, namun tanpa grafik fungsi keanggotaan (μ(x)).<o:p></o:p></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Saran: Tambahkan grafik segitiga/trapesium untuk setiap variabel input fuzzy.<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><o:p>&nbsp;</o:p></p><p class=\"MsoListParagraphCxSpFirst\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 14pt;\">6.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size: 14pt;\">Kutipan Ilmiah Kurang Konsisten<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Ada kutipan seperti (Sugiyono, 2015), (Zainuddin, 2022), namun belum terlihat daftar pustaka atau format gaya kutipan (APA, IEEE).<o:p></o:p></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Saran: Konsistenkan dan sertakan daftar pustaka sesuai dengan pedoman institusi.<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><o:p>&nbsp;</o:p></p><p class=\"MsoListParagraphCxSpFirst\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 14pt;\">7.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size: 14pt;\">Penutup Bab II Tidak Ada<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Langsung berakhir di kajian pustaka tanpa kesimpulan atau transisi ke bab berikutnya.<o:p></o:p></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Saran: Tambahkan paragraf penutup:<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0cm 3cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\">\"Bab ini telah membahas teori-teori dasar yang menjadi landasan pengembangan sistem SPK berbasis Fuzzy SAW untuk seleksi peserta Kelas Khusus Qur’an. Teori-teori tersebut menjadi dasar penerapan pada tahapan implementasi dan perancangan sistem yang dijelaskan pada Bab III.\"<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><o:p>&nbsp;</o:p></p>', '/ekapta-app-new/storage/app/public/lampirans/oHpYO2mH2zR971YWa7OvOju4I8vaaLMMQjtbRInA.pdf', NULL, '2025-06-16 10:10:22', '2025-06-22 17:59:00', '2025-06-22 17:59:00', 1722, 19);
INSERT INTO `revisi_bimbingans` (`id`, `catatan`, `lampiran`, `lampiran_revisi`, `tanggal_bimbingan`, `created_at`, `updated_at`, `bimbingan_id`, `dosen_id`) VALUES
(1411, '<p class=\"MsoListParagraphCxSpFirst\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 14pt;\">1.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size: 14pt;\">DFD, ERD, dan Flowchart Hanya Disebutkan, Tidak Ditampilkan<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Masalah: Terdapat rujukan seperti “Gambar 2.1 DFD Level 0” dan “Gambar 2.4 Flowchart”, namun tidak ada visual diagram yang disisipkan.<o:p></o:p></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Saran: Tambahkan gambar asli dari:<o:p></o:p></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 72pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: &quot;Courier New&quot;;\">o<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp; </span></span>DFD Level 0 &amp; Level 1<o:p></o:p></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 72pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: &quot;Courier New&quot;;\">o<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp; </span></span>ERD sistem seleksi<o:p></o:p></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 72pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: &quot;Courier New&quot;;\">o<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp; </span></span>Flowchart sistem SPK<o:p></o:p></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Gunakan tools seperti draw.io, Lucidchart, atau Figma.<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><span style=\"font-family: &quot;Times New Roman&quot;, serif;\">&nbsp;</span></p><p class=\"MsoListParagraphCxSpFirst\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 14pt;\">2.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size: 14pt;\">Subbab Efisiensi Waktu Terlalu Panjang<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Masalah: Subbab 2.3 dan 2.4 tentang efisiensi waktu cukup panjang dan dapat menurunkan fokus pembaca terhadap teori utama (Fuzzy SAW).<o:p></o:p></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Saran: Ringkas menjadi satu bagian dengan judul:<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0cm 3cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\">“Peran Efisiensi Waktu dalam Sistem Seleksi”<br>dan cukup masukkan esensinya (tanpa perlu terlalu banyak narasi berulang).<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><span style=\"font-family: &quot;Times New Roman&quot;, serif;\">&nbsp;</span></p><p class=\"MsoListParagraphCxSpFirst\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 14pt;\">3.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size: 14pt;\">Perhitungan Fuzzy SAW Belum Diberi Contoh<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Masalah: Langkah-langkah Fuzzy SAW dijelaskan baik, namun tanpa ilustrasi tabel atau contoh angka.<o:p></o:p></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Saran: Tambahkan contoh sederhana:<o:p></o:p></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 72pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: &quot;Courier New&quot;;\">o<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp; </span></span>3 alternatif, 3 kriteria<o:p></o:p></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 72pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: &quot;Courier New&quot;;\">o<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp; </span></span>Penilaian linguistik → konversi fuzzy<o:p></o:p></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin: 0cm 0cm 0cm 72pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: &quot;Courier New&quot;;\">o<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp; </span></span>Normalisasi → pembobotan → defuzzifikasi → peringkat<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><span style=\"font-family: &quot;Times New Roman&quot;, serif;\">&nbsp;</span></p><p class=\"MsoListParagraph\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 14pt;\">4.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size: 14pt;\">Diagram Fungsi Keanggotaan Fuzzy Tidak Ada<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 10pt; font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span><b><span style=\"font-family: &quot;Times New Roman&quot;, serif;\">Masalah:</span></b><span style=\"font-family: &quot;Times New Roman&quot;, serif;\"> Fungsi keanggotaan segitiga hanya dijelaskan secara rumus.<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 10pt; font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span><b><span style=\"font-family: &quot;Times New Roman&quot;, serif;\">Saran:</span></b><span style=\"font-family: &quot;Times New Roman&quot;, serif;\"> Tambahkan <b>grafik fungsi keanggotaan fuzzy</b> (μ(x)) untuk nilai rendah, sedang, tinggi dsb.<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpFirst\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 14pt;\">5.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size: 14pt;\">Nomor Subbab Banyak yang Tidak Konsisten<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Misalnya: Subbab 2.2 → 2.3 → 2.3 lagi (harusnya 2.4), dst.<o:p></o:p></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Saran: Periksa dan perbaiki seluruh penomoran subbab agar konsisten dan mengikuti struktur akademik baku.<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><span style=\"font-family: &quot;Times New Roman&quot;, serif;\">&nbsp;</span></p><p class=\"MsoListParagraphCxSpFirst\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 14pt;\">6.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size: 14pt;\">Simbol DFD dan ERD Ditulis di Tabel, Tidak Perlu di Utama<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Lebih baik tabel simbol-simbol ERD/DFD dipindah ke lampiran, agar bagian utama tidak penuh teori dasar teknis yang umum diketahui pembaca teknis.<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><span style=\"font-family: &quot;Times New Roman&quot;, serif;\">&nbsp;</span></p><p class=\"MsoListParagraphCxSpFirst\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 14pt;\">7.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size: 14pt;\">Referensi Perlu Diperbanyak dan Diperbarui<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Beberapa referensi masih umum dan lama (seperti McLeod 2001). Sebaiknya tambahkan:<o:p></o:p></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 72pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: &quot;Courier New&quot;;\">o<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp; </span></span>Jurnal atau konferensi 5 tahun terakhir<o:p></o:p></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin: 0cm 0cm 0cm 72pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: &quot;Courier New&quot;;\">o<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp; </span></span>Artikel terindeks SINTA, IEEE, atau jurnal prodi TI/TK relevan<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><o:p>&nbsp;</o:p></p>', '/ekapta-app-new/storage/app/public/lampirans/oHpYO2mH2zR971YWa7OvOju4I8vaaLMMQjtbRInA.pdf', NULL, '2025-06-16 10:10:22', '2025-06-22 18:59:57', '2025-06-22 18:59:57', 1722, 19),
(1412, '<p class=\"MsoListParagraphCxSpFirst\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 14pt;\">1.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size: 14pt;\">Kerangka Pikir Tidak Ditampilkan<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Masalah: Hanya disebut “lihat gambar 3.2”, namun gambar kerangka pikir tidak disertakan dalam file.<o:p></o:p></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Saran: Tambahkan bagan kerangka pikir yang menggambarkan hubungan:<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0cm 3cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><o:p>&nbsp;</o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0cm 3cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\">Masalah → Data Penginapan &amp; Preferensi → Pemilihan Kriteria → SAW → Hasil Rekomendasi<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: 36pt;\">Gunakan tools seperti draw.io, Canva, atau Word SmartArt.<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><span style=\"font-family: &quot;Times New Roman&quot;, serif;\">&nbsp;</span></p><p class=\"MsoListParagraphCxSpFirst\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 14pt;\">2.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size: 14pt;\">Alur Penelitian Juga Hanya Teks, Tanpa Diagram<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Sama seperti kerangka pikir, alur disebut dalam teks tapi tidak ada visual alur proses penelitian.<o:p></o:p></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Saran: Tambahkan flowchart alur penelitian:<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0cm 92.15pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><o:p>&nbsp;</o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0cm 92.15pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\">Identifikasi Masalah → Pengumpulan Data → Perancangan Sistem → Implementasi → Pengujian → Evaluasi<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><span style=\"font-family: &quot;Times New Roman&quot;, serif;\">&nbsp;</span></p><p class=\"MsoListParagraphCxSpFirst\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 14pt;\">3.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size: 14pt;\">Belum Ada Detail tentang Bobot Kriteria dan Contoh Perhitungan<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Disebutkan bahwa bobot berasal dari kuesioner, tapi tidak ada tabel bobot maupun perhitungan SAW yang ditampilkan.<o:p></o:p></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Saran: Tambahkan:<o:p></o:p></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 72pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: &quot;Courier New&quot;;\">o<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp; </span></span>Tabel kriteria dan bobot (misal: Harga = 0.4, Fasilitas = 0.3, dll.)<o:p></o:p></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin: 0cm 0cm 0cm 72pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: &quot;Courier New&quot;;\">o<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp; </span></span>Tabel normalisasi dan hasil nilai preferensi dari minimal 3 alternatif penginapan.<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><span style=\"font-family: &quot;Times New Roman&quot;, serif;\">&nbsp;</span></p><p class=\"MsoListParagraphCxSpFirst\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 14pt;\">4.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size: 14pt;\">Tidak Ada Penjelasan Tentang Pengujian Sistem<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Masalah: Bab ini menyebut pengembangan sistem, tapi tidak menyertakan metode pengujian sistem.<o:p></o:p></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Saran: Tambahkan satu subbab tambahan seperti:<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0cm 92.15pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><o:p>&nbsp;</o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0cm 92.15pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\">3.7 Metode Pengujian Sistem<br>Jelaskan pengujian fungsional (black-box) terhadap fitur-fitur sistem dan validasi hasil SAW.<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><span style=\"font-family: &quot;Times New Roman&quot;, serif;\">&nbsp;</span></p><p class=\"MsoListParagraphCxSpFirst\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 14pt;\">5.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size: 14pt;\">Sumber Referensi Tidak Disebut dalam Analisis Data<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Ada kutipan dari Sugiyono (2014) dalam analisis data, tapi tidak dicantumkan secara konsisten.<o:p></o:p></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Saran: Pastikan kutipan tersebut masuk daftar pustaka dan gunakan gaya kutipan akademik (APA, IEEE, dll.)<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><o:p>&nbsp;</o:p></p>', '/ekapta-app-new/storage/app/public/lampirans/4uhfZWc0UJ3QoaL5Z3mvdH4XdoZnsVHi8TKrOWB5.pdf', NULL, '2025-06-16 08:57:26', '2025-06-22 19:13:24', '2025-06-22 19:13:24', 669, 19);
INSERT INTO `revisi_bimbingans` (`id`, `catatan`, `lampiran`, `lampiran_revisi`, `tanggal_bimbingan`, `created_at`, `updated_at`, `bimbingan_id`, `dosen_id`) VALUES
(1413, '<p class=\"MsoListParagraphCxSpFirst\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 14pt;\">1.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size: 14pt;\">Diagram UML Tidak Ditampilkan<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Masalah: Subbagian Use Case dan Activity Diagram hanya menyebut tabel simbol dan keterangan, tanpa menampilkan diagram aktual.<o:p></o:p></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Saran: Tambahkan gambar:<o:p></o:p></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 72pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: &quot;Courier New&quot;;\">o<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp; </span></span>Use Case Diagram (aktor: pengguna, sistem)<o:p></o:p></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin: 0cm 0cm 0cm 72pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: &quot;Courier New&quot;;\">o<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp; </span></span>Activity Diagram (alur klasifikasi dari input gambar → prediksi → output)<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><span style=\"font-family: &quot;Times New Roman&quot;, serif;\">&nbsp;</span></p><p class=\"MsoListParagraphCxSpFirst\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 14pt;\">2.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size: 14pt;\">Struktur Subbab Perangkat Pendukung Perlu Diperbaiki<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Masalah: Nomor subbab seperti 2.1.8.1 Python dan 2.1.9.1 Google Colab tampak tidak konsisten (berikutnya justru kembali ke 2.1.9).<o:p></o:p></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Saran: Perbaiki sistem penomoran subbab agar:<o:p></o:p></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin: 0cm 0cm 0cm 72pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: &quot;Courier New&quot;;\">o<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp; </span></span>Python dan Google Colab menjadi 2.1.8.1 dan 2.1.8.2 sebagai bagian dari 2.1.8 Tools Pendukung, atau buat masing-masing jadi 2.1.8 dan 2.1.9 jika dipisah.<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><span style=\"font-family: &quot;Times New Roman&quot;, serif;\">&nbsp;</span></p><p class=\"MsoListParagraphCxSpFirst\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 14pt;\">3.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size: 14pt;\">Perlu Penjelasan Dataset<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 2cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -21.25pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Masalah: Tidak dijelaskan jumlah dataset, sumber gambar, dan distribusi kelas (mentah, setengah matang, matang).<o:p></o:p></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin: 0cm 0cm 0cm 2cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -21.25pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Saran: Tambahkan deskripsi seperti:<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0cm 92.15pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\">\"Dataset terdiri dari 900 citra stroberi, masing-masing 300 gambar untuk setiap kelas. Data dikumpulkan dari sumber X dengan augmentasi rotasi dan zoom.\"<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><span style=\"font-family: &quot;Times New Roman&quot;, serif;\">&nbsp;</span></p><p class=\"MsoListParagraphCxSpFirst\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 14pt;\">4.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size: 14pt;\">Penjelasan Arsitektur MobileNet Masih Umum<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 2cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -21.25pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Masalah: MobileNet dijelaskan secara naratif, tapi tidak menampilkan detail arsitekturnya (misal blok layer).<o:p></o:p></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin: 0cm 0cm 0cm 2cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -21.25pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Saran: Tambahkan deskripsi singkat layer khas MobileNetV2 seperti:<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0cm 92.15pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\">\"Inverted Residual Blocks, Bottleneck Layers, Linear Bottleneck Activation.\"<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><span style=\"font-family: &quot;Times New Roman&quot;, serif;\">&nbsp;</span></p><p class=\"MsoListParagraphCxSpFirst\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 14pt;\">5.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size: 14pt;\">Visualisasi Data Augmentation Tidak Ada<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Masalah: Dijelaskan ada augmentasi (flip, rotasi), tapi tanpa contoh gambar atau ilustrasi.<o:p></o:p></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Saran: Tambahkan gambar: gambar asli → gambar hasil augmentasi (rotasi, zoom, flip horizontal)<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><span style=\"font-family: &quot;Times New Roman&quot;, serif;\">&nbsp;</span></p><p class=\"MsoListParagraphCxSpFirst\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 14pt;\">6.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size: 14pt;\">Evaluasi (Confusion Matrix) Belum Dihubungkan dengan Kinerja Model<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Masalah: Metrik seperti accuracy, recall, F1 dijelaskan, namun tidak ada pengantar atau alasan kenapa metrik ini relevan untuk klasifikasi multiclass.<o:p></o:p></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Saran: Tambahkan kalimat seperti:<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0cm 3cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\">\"Metrik ini digunakan untuk mengevaluasi model klasifikasi tiga kelas yang bersifat tidak seimbang.\"<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><span style=\"font-family: &quot;Times New Roman&quot;, serif;\">&nbsp;</span></p><p class=\"MsoListParagraph\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 14pt;\">7.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size: 14pt;\">Tidak Ada Kutipan Pada Beberapa Klaim Teknis<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 10pt; font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Masalah: Beberapa definisi teknis penting (contoh CNN layer, MobileNetV2) tidak diberi rujukan eksplisit ke sumber.<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 10pt; font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Saran: Tambahkan kutipan dari jurnal, dokumentasi TensorFlow/Keras, atau artikel ilmiah terpercaya.<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><o:p>&nbsp;</o:p></p>', '/ekapta-app-new/storage/app/public/lampirans/HKSqLfBxo3ZjIVRMZyx7cSUG2THaQkWhWd9MQz8Q.pdf', NULL, '2025-06-23 02:48:20', '2025-06-23 04:15:08', '2025-06-23 04:15:08', 1894, 19),
(1414, '<p class=\"MsoListParagraphCxSpFirst\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 14pt;\">1.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size: 14pt;\">Judul Tidak Konsisten<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Di beberapa bagian tertulis “menu siap saji”, tetapi pada akhir latar belakang dan tujuan tertulis “menu siap jual”.<o:p></o:p></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Saran: Gunakan satu istilah yang konsisten sepanjang dokumen. Jika merujuk pada makanan yang siap dikonsumsi, gunakan “menu siap saji”.<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><span style=\"font-family: &quot;Times New Roman&quot;, serif;\">&nbsp;</span></p><p class=\"MsoListParagraphCxSpFirst\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 14pt;\">2.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size: 14pt;\">Latar Belakang Terlalu Panjang dan Teoretis di Awal<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Bagian awal terlalu fokus pada teori sistem informasi umum.<o:p></o:p></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Saran: Singkatkan teori dasar dan langsung masuk ke masalah spesifik RM Gendu Roso dan urgensi prediksi stok.<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><span style=\"font-family: &quot;Times New Roman&quot;, serif;\">&nbsp;</span></p><p class=\"MsoListParagraphCxSpFirst\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 14pt;\">3.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size: 14pt;\">Batasan Masalah Belum Terstruktur dengan Baik<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Butir poinnya sudah ada, tetapi tidak semua dijabarkan dengan jelas.<o:p></o:p></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Saran:<o:p></o:p></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 72pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: &quot;Courier New&quot;;\">o<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp; </span></span>Tambahkan penjelasan singkat per poin.<o:p></o:p></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 72pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: &quot;Courier New&quot;;\">o<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp; </span></span>Contoh:<o:p></o:p></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin: 0cm 0cm 0cm 90pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\">C.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp; </span>Periode prediksi dilakukan untuk 1 bulan ke depan, dengan asumsi data historis tersedia setiap hari.<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><span style=\"font-family: &quot;Times New Roman&quot;, serif;\">&nbsp;</span></p><p class=\"MsoListParagraphCxSpFirst\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 14pt;\">4.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size: 14pt;\">Istilah Algoritma Fuzzy Mamdani Perlu Penjelasan Singkat<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Di latar belakang, algoritma langsung disebutkan tanpa deskripsi singkat.<o:p></o:p></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Saran: Tambahkan 1 kalimat:<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0cm 108pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\">\"Fuzzy Mamdani adalah metode inferensi berbasis aturan yang mampu menangani ketidakpastian melalui pendekatan linguistik.\"<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><span style=\"font-family: &quot;Times New Roman&quot;, serif;\">&nbsp;</span></p><p class=\"MsoListParagraphCxSpFirst\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 14pt;\">5.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size: 14pt;\">Rumusan Masalah Bisa Dipertajam<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Saat ini cukup baik, tapi bisa ditambahkan fokus sistem dan implementasinya.<o:p></o:p></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Saran: Ubah menjadi:<o:p></o:p></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 99.25pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -14.2pt;\">a.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp; </span>Bagaimana membangun sistem prediksi persediaan menu siap saji menggunakan algoritma Fuzzy Mamdani?<o:p></o:p></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin: 0cm 0cm 0cm 99.25pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -14.2pt;\">b.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp; </span>Bagaimana mengukur akurasi hasil prediksi dengan metode evaluasi MAE, RMSE, dan MAPE?<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><span style=\"font-family: &quot;Times New Roman&quot;, serif;\">&nbsp;</span></p><p class=\"MsoListParagraphCxSpFirst\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 14pt;\">6.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size: 14pt;\">Sistematika Penulisan Masih Naratif<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Kalimatnya seperti “Bab ini membahas...”, terlalu deskriptif.<o:p></o:p></p><p class=\"MsoListParagraphCxSpLast\" style=\"margin: 0cm 0cm 0cm 54pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-family: Symbol;\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Saran: Gunakan bentuk struktur kalimat ringkas:<span style=\"font-family: &quot;Times New Roman&quot;, serif;\"><o:p></o:p></span></p><p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0cm 92.15pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\">Bab I membahas pendahuluan. Bab II menyajikan teori dasar dan kajian pustaka. Bab III menjelaskan metodologi penelitian. Bab IV memaparkan hasil dan pembahasan. Bab V menyimpulkan dan memberikan saran pengembangan.<o:p></o:p></p><p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><span style=\"font-family: &quot;Times New Roman&quot;, serif;\">&nbsp;</span></p><p class=\"MsoListParagraph\" style=\"margin: 0cm 0cm 0cm 36pt; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0); text-indent: -18pt;\"><span style=\"font-size: 14pt;\">7.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size: 14pt;\">Manfaat IPTEK dan Peneliti Masih Umum<o:p></o:p></span></p><ul type=\"disc\" style=\"margin-bottom: 0cm; color: rgb(0, 0, 0); font-size: medium;\"><li class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif;\">Penjelasan manfaat bagi IPTEK dan peneliti cenderung umum.<o:p></o:p></li><li class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif;\">Saran: Kaitkan manfaat IPTEK langsung ke pengembangan sistem prediksi stok makanan berbasis AI.<o:p></o:p></li></ul><p class=\"MsoNormal\" style=\"margin: 0cm; font-size: 12pt; font-family: Calibri, sans-serif; color: rgb(0, 0, 0);\"><o:p>&nbsp;</o:p></p>', '/ekapta-app-new/storage/app/public/lampirans/BwFM0lgKkopiKrEWH1cLbKRHGTnk0CHmFAU48yuw.pdf', NULL, '2025-06-23 04:01:42', '2025-06-23 04:40:44', '2025-06-23 04:40:44', 1807, 19),
