INSERT INTO `revisi_ujians` (`id`, `catatan`, `lampiran`, `created_at`, `updated_at`, `ujian_id`) VALUES
(2, '<p class=\"MsoNormal\" style=\"text-align:justify\"><b><i><span lang=\"EN-US\">Assalamu’alaikum Warahmatullahi Wabarakatuh<o:p></o:p></span></i></b></p><p class=\"MsoNormal\" style=\"text-align:justify\"><span lang=\"EN-US\">Kami beritahukan bahwa untuk pendaftaran Ujian\r\nPendadaran anda kami <b>TOLAK</b>, karena masih ada kekurangan berkas yaitu:</span></p><ol><li style=\"text-align: justify;\"><span lang=\"EN-US\">Scan Ijazah Asli / Scan FC Ijazah yang dilegalisir</span></li></ol><p class=\"MsoNormal\" style=\"text-align:justify\"><span lang=\"EN-US\">Segera lengkapi berkas anda kemudian isi ulang\r\nform pendaftaran Ujian Pendadaran melalui link: </span><a href=\"https://forms.gle/cJtjxfqTZWgKuzVc8\"><span lang=\"EN-US\">https://forms.gle/cJtjxfqTZWgKuzVc8</span></a><span lang=\"EN-US\">. Demikian pemberitahuan ini kami sampaikan,\r\natas perhatiannya kami haturkan terima kasih.<o:p></o:p></span></p><p>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n</p><p class=\"MsoNormal\" style=\"text-align:justify\"><b><i><span lang=\"EN-US\">Wassalamu’alaikum Warahmatullahi Wabarakatuh<o:p></o:p></span></i></b></p>', NULL, '2024-07-09 02:31:00', '2024-07-09 02:31:00', 19),
(3, '<p class=\"MsoNormal\" style=\"text-align:justify\"><b><i><span lang=\"EN-US\">Assalamu’alaikum Warahmatullahi Wabarakatuh<o:p></o:p></span></i></b></p><p class=\"MsoNormal\" style=\"text-align:justify\"><span lang=\"EN-US\">Kami beritahukan bahwa untuk pendaftaran Ujian\r\nPendadaran anda kami <b>TOLAK</b>, karena masih ada kekurangan berkas yaitu:</span></p><ol><li style=\"text-align: justify;\"><span lang=\"EN-US\">Pembayaran SPP Semester berjalan</span></li></ol><p class=\"MsoNormal\" style=\"text-align:justify\"><span lang=\"EN-US\">Segera lengkapi berkas anda kemudian isi ulang\r\nform pendaftaran Ujian Pendadaran melalui link: </span><a href=\"https://forms.gle/cJtjxfqTZWgKuzVc8\"><span lang=\"EN-US\">https://forms.gle/cJtjxfqTZWgKuzVc8</span></a><span lang=\"EN-US\">. Demikian pemberitahuan ini kami sampaikan,\r\natas perhatiannya kami haturkan terima kasih.<o:p></o:p></span></p><p>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n</p><p class=\"MsoNormal\" style=\"text-align:justify\"><b><i><span lang=\"EN-US\">Wassalamu’alaikum Warahmatullahi Wabarakatuh<o:p></o:p></span></i></b></p>', NULL, '2024-07-09 02:39:17', '2024-07-09 02:39:17', 11),
(4, '<p class=\"MsoNormal\" style=\"text-align:justify\"><b><i><span lang=\"EN-US\">Assalamu’alaikum Warahmatullahi Wabarakatuh<o:p></o:p></span></i></b></p><p class=\"MsoNormal\" style=\"text-align:justify\"><span lang=\"EN-US\">Kami beritahukan bahwa untuk pendaftaran Ujian\r\nPendadaran anda kami <b>TOLAK</b>, karena masih ada kekurangan berkas yaitu:</span></p><ol><li style=\"text-align: justify;\"><span lang=\"EN-US\">Scan Sertifikat Tahfid yang asli / bukti pendaftaran yang baru</span></li></ol><p class=\"MsoNormal\" style=\"text-align:justify\"><span lang=\"EN-US\">Segera lengkapi berkas anda kemudian isi ulang\r\nform pendaftaran Ujian Pendadaran melalui link: </span><a href=\"https://forms.gle/cJtjxfqTZWgKuzVc8\"><span lang=\"EN-US\">https://forms.gle/cJtjxfqTZWgKuzVc8</span></a><span lang=\"EN-US\">. Demikian pemberitahuan ini kami sampaikan,\r\natas perhatiannya kami haturkan terima kasih.<o:p></o:p></span></p><p>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n</p><p class=\"MsoNormal\" style=\"text-align:justify\"><b><i><span lang=\"EN-US\">Wassalamu’alaikum Warahmatullahi Wabarakatuh<o:p></o:p></span></i></b></p>', NULL, '2024-07-09 02:43:02', '2024-07-09 02:43:02', 7),
